/**
 * r2-34-propose-rows.mjs - turn the discovery misses (R14 list (c)) into registry rows (Task 923)
 *
 *   node docs/sessions/evidence/task923/r2-34-propose-rows.mjs <discover.json> <proposed.json> [--apply]
 * The first-pass registry was generated by a script that lived in a session scratchpad (review finding 4). This is its
 * replacement and it is committed with the evidence. Input: `<out>/discover.json` of `--discover --out <dir>`. For
 * every miss group (Story + trigger tag + label) it
 *   1. builds the open selector: the structural path(s) of the trigger at the widths it was found, `:scope > ` in front,
 *      joined with ", " when the path differs between widths (a responsive twin);
 *   2. opens the state at the widest width where it opens and classifies it: portals (the count that opened), focus
 *      (`trap` for a modal dialog or sheet, `inside` when the focus moved into a portal, else `trigger`), and dismiss
 *      (each mechanism is exercised with the gate's own dismiss check; a mechanism is declared when it closes the
 *      overlay; an overlay no mechanism closes carries a `reason`);
 *   3. probes the trigger at every theme breakpoint and breakpoint minus 1 and derives `widths` from where it opens.
 * `--apply` inserts the new rows into `scripts/rendered-interaction-states.json`, each after the last row of its Story.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { cpus } from 'node:os';
import { createRequire } from 'node:module';
import { loadBreakpoints } from '../../../../scripts/rendered-state-census/theme-breakpoints.mjs';
import { validateRegistry } from '../../../../scripts/rendered-state-census/registry.mjs';
import {
  DEFAULT_CLOSE_SELECTOR, dismissCheck, loadStory, newMeasuringPage, openAction, runPool, startStaticServer, storybookContext, waitStable,
} from '../../../../scripts/rendered-state-census/runner.mjs';

const require = createRequire(import.meta.url);
const { chromium } = require('playwright');
const [inPath, outPath, flag] = process.argv.slice(2);
if (!inPath || !outPath) throw new Error('usage: node r2-34-propose-rows.mjs <discover.json> <proposed.json> [--apply]');

const { list } = loadBreakpoints(process.cwd());
// 319 (the smallest breakpoint minus 1) is no real viewport: the floor is the smallest breakpoint itself
const probeWidths = [...new Set(list.flatMap((b, i) => (i === 0 ? [b] : [b - 1, b])))].sort((a, b) => a - b);
const registryPath = 'scripts/rendered-interaction-states.json';
const registry = JSON.parse(readFileSync(registryPath, 'utf8'));
const discover = JSON.parse(readFileSync(inPath, 'utf8'));

const slug = (s) => s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40) || 'trigger';
const taken = new Set(registry.states.map((s) => s.id));

// ---- group the misses ----
const groups = new Map();
for (const m of discover.misses) {
  const key = `${m.story}|${m.tag}|${m.label}`;
  const g = groups.get(key) ?? { story: m.story, tag: m.tag, label: m.label, byWidth: new Map() };
  g.byWidth.set(m.width, [...new Set([...(g.byWidth.get(m.width) ?? []), m.sel])]);
  groups.set(key, g);
}

// Wide variants that first open at 641px, not at the theme's 640px (bisect: `r2-42-problem-bisect.txt` - unclickable 320..640,
// opens 641..1440). `widths` can only name a theme breakpoint, so the CONTRACT range { min: 640 } is registered and the gate
// itself reports the one-pixel disagreement at 640 (a product off-by-one), instead of the registry hiding it.
const OFF_BY_ONE_WIDE = [/^mantine-primitives-rangedatepicker--/, /^patterns-mantine-userpickerfieldview--/];

function derive(openWidths, story) {
  if (OFF_BY_ONE_WIDE.some((re) => re.test(story)) && openWidths.length && openWidths[0] === 767) return { widths: { min: 640 } };
  if (openWidths.length === 0) return { problem: 'opens at no probed width' };
  const lo = openWidths[0];
  const hi = openWidths[openWidths.length - 1];
  if (probeWidths.filter((w) => w >= lo && w <= hi).length !== openWidths.length) return { problem: `opens at ${openWidths.join(',')} - not one contiguous run` };
  const widths = {};
  if (lo > probeWidths[0]) { if (!list.includes(lo)) return { problem: `lowest opening width ${lo} is not a theme breakpoint` }; widths.min = lo; }
  if (hi < probeWidths[probeWidths.length - 1]) { if (!list.includes(hi + 1)) return { problem: `highest opening width ${hi} is not a breakpoint minus 1` }; widths.max = hi; }
  return { widths: Object.keys(widths).length ? widths : undefined };
}

const server = await startStaticServer('storybook-static', 6045);
const browser = await chromium.launch();
const ctx = storybookContext('http://127.0.0.1:6045');
const proposed = [];
const problems = [];

const only = process.env.ONLY_STORY_PREFIX ? new RegExp(process.env.ONLY_STORY_PREFIX) : null;
const jobs = [...groups.values()].filter((g) => !only || only.test(g.story)).map((g) => ({
  target: { story: g.story, state: 'propose', locale: 'en', width: 390 },
  run: async (page) => {
    const selectors = [...new Set([...g.byWidth.values()].flat())].map((p) => `:scope > ${p}`);
    const selector = selectors.join(', ');
    const base = { kind: 'click', selector };
    const tmp = { id: 'tmp', story: g.story, open: base, portals: 1, focus: 'trigger', dismiss: [], trigger: selector };

    // 3. probe the trigger at every probe width
    const openWidths = [];
    for (const width of probeWidths) {
      const loaded = await loadStory(page, ctx, { story: g.story, state: 'p', locale: 'en', width });
      if (!loaded.ok) continue;
      if ((await page.locator('#storybook-root').locator(selector).filter({ visible: true }).count()) === 0) continue;
      const o = await openAction(page, tmp);
      if (o.ok && (await waitStable(page, null, 2500)) > 0) openWidths.push(width);
    }
    const derived = derive(openWidths, g.story);
    if (derived.problem) { problems.push(`${g.story} ${g.tag} "${g.label}": ${derived.problem}`); return []; }

    // 2. classify at the widest width where it opens
    const width = openWidths[openWidths.length - 1];
    const at = { story: g.story, state: 'p', locale: 'en', width };
    await loadStory(page, ctx, at);
    await openAction(page, tmp);
    const portals = await waitStable(page, null, 3000);
    const fl = await page.evaluate((sel) => window.__census.flavor(sel), DEFAULT_CLOSE_SELECTOR);
    const f = await page.evaluate((t) => window.__census.focusState(t), selector);
    const focus = fl.modal ? 'trap' : f.portalIndex >= 0 ? 'inside' : 'trigger';
    const dismiss = [];
    const notes = [];
    for (const mechanism of ['escape', 'close-control', 'outside']) {
      const r = await dismissCheck(page, ctx, { ...tmp, focus, portals }, 'en', width, mechanism, false);
      const notClosed = r.details.some((d) => /still visible|cannot be clicked|matches nothing|no point outside|no portal is open/.test(d));
      if (!notClosed && !r.na) dismiss.push(mechanism);
      else notes.push(`${mechanism}: ${r.na ? 'not applicable' : 'does not close'}`);
    }
    const state = {
      id: '', story: g.story, open: base, portals, focus, dismiss,
      ...(dismiss.length === 0 ? { reason: 'no dismissal mechanism closes the overlay in the Story harness (its onClose is a no-op)' } : {}),
      trigger: selector, ...(derived.widths ? { widths: derived.widths } : {}),
    };
    let id = `${g.story}~${slug(g.label)}`;
    for (let i = 2; taken.has(id); i++) id = `${g.story}~${slug(g.label)}-${i}`;
    taken.add(id);
    state.id = id;
    proposed.push({ ...state, _notes: notes.join('; ') });
    return [];
  },
}));
await runPool(browser, jobs, Math.max(2, Math.min(8, cpus().length - 2)), () => {});
await browser.close();
await new Promise((r) => server.close(r));

proposed.sort((a, b) => a.id.localeCompare(b.id));
writeFileSync(outPath, JSON.stringify({ groups: groups.size, proposed, problems }, null, 2) + '\n');
console.log(`miss groups ${groups.size}: proposed ${proposed.length} rows, ${problems.length} problem(s)`);
for (const p of problems) console.log(`  PROBLEM ${p}`);

if (flag === '--apply') {
  if (problems.length) throw new Error('not applying: resolve the problems first');
  const states = registry.states.slice();
  for (const row of proposed) {
    const { _notes, ...clean } = row;
    let at = -1;
    states.forEach((s, i) => { if (s.story === clean.story) at = i; });
    if (at < 0) states.push(clean); else states.splice(at + 1, 0, clean);
  }
  const next = { ...registry, states };
  const bps = list;
  const index = JSON.parse(readFileSync('storybook-static/index.json', 'utf8')).entries;
  const check = validateRegistry(next, { index, breakpoints: bps });
  if (!check.ok) throw new Error(`the extended registry is invalid:\n${check.errors.join('\n')}`);
  writeFileSync(registryPath, JSON.stringify(next, null, 2) + '\n');
  console.log(`applied: registry ${registry.states.length} -> ${states.length} rows`);
}
